package org.runerealm.server.app

import com.github.michaelbull.logging.InlineLogger
import io.netty.buffer.Unpooled
import org.openrs2.cache.Cache

/**
 * Packs the RuneRealm login screen into the client (js5) cache: the background `title.jpg` and the
 * `logo` sprite, which carries the right half of the background so it is not mirrored. The assets
 * are generated by `Branding Resources/build_client_branding.py`.
 */
internal object ClientBranding {
    private val logger = InlineLogger()

    private const val BINARY_ARCHIVE = 10
    private const val SPRITE_ARCHIVE = 8

    fun apply(cache: Cache) {
        val updated =
            write(cache, BINARY_ARCHIVE, "title.jpg", resource("title.jpg")) or
                write(cache, SPRITE_ARCHIVE, "logo", resource("logo.dat"))
        if (updated) {
            cache.flush()
            logger.info { "Packed RuneRealm login screen into the client cache." }
        }
    }

    private fun write(cache: Cache, archive: Int, group: String, bytes: ByteArray): Boolean {
        val current =
            if (cache.exists(archive, group)) {
                cache.read(archive, group, 0).use { buf ->
                    ByteArray(buf.readableBytes()).also(buf::readBytes)
                }
            } else {
                null
            }
        if (current != null && current.contentEquals(bytes)) {
            return false
        }
        cache.write(archive, group, 0, Unpooled.wrappedBuffer(bytes))
        return true
    }

    private fun resource(name: String): ByteArray {
        val stream =
            ClientBranding::class.java.getResourceAsStream("branding/$name")
                ?: error("Missing branding resource: $name")
        return stream.use { it.readBytes() }
    }
}

private inline fun <T> io.netty.buffer.ByteBuf.use(block: (io.netty.buffer.ByteBuf) -> T): T =
    try {
        block(this)
    } finally {
        release()
    }
